const rl = require('readline-sync')

let salariobase = parseFloat(rl.question("ingrese el salario base:"))
let bono = parseFloat(rl.question("ingrese el valor del bono fijo:"))
let horasextras = parseFloat(rl.question("ingrese la cantidad de horas extras:"))
let valorhoraextra = parseFloat(rl.question("ingrese el valor por hora extra:"))

let totalextras = horasextras * valorhoraextra
let salariototal = salariobase + bono + totalextras

console.log("salario total: "+salariototal.toFixed(2))